/**
 * TAB 2 - "ANIMATION"
 * -------------------
 * A viewer and keyframe editor for the hero's cut-out skeleton
 * (content/rigs/hero.rig.json).
 *
 *   left ..... the list of animations, and the bone tree
 *   middle ... the stage (pose the hero), play controls, the timeline
 *   right .... number boxes for the selection, blend times, sequence tester
 *
 * What can be edited here: ANIMATIONS (keys, events, length, blend times).
 * What cannot (yet): the setup pose - bone positions and the body-part pictures
 * are shown read-only.
 *
 * NOTE: hero.rig.json is normally GENERATED by `npm run art` from
 * tools/art/hero-anims.mjs. Saving here writes the JSON directly, so
 * re-running `npm run art` would overwrite edits made in this editor.
 */
import { saveContent } from '../../../shared/api';
import { CONTENT, type RigData } from '../../../shared/types';
import { sampleAnimation, type LocalPose } from '../../../rig/pose';
import { toast } from '../../common/nav';
import {
  blankAnimation, checkAnimName, cloneAnimation, copyPoseAt, deleteAnimation, deleteEvent, isProtectedAnim, keyAllBones,
  pastePoseAt, renameAnimation, roundTime, sampleOffset, snapTime, uniqueAnimName, withAnimation, addEvent,
} from '../logic/keyframes';
import { PosePlayer, SequenceRunner, type SequenceStep } from '../logic/posePlayer';
import type { EditorTab, Shell } from '../tabs';
import { askConfirm, askText, button, clear, downloadJson, h, pickJsonFile, toggleButton, type ToggleButton } from '../ui/dom';
import { Inspector } from './inspector';
import { AnimModel, type ChangeKind, type Tool } from './model';
import { BACKGROUNDS, Stage } from './stage';
import { Timeline } from './timeline';

const DRAFT_KEY = 'gameEditor.rigDraft.v1';

export class AnimTab implements EditorTab {
  id = 'anim';
  label = '🦴 Animation';
  el: HTMLElement;

  private model: AnimModel;
  private stage: Stage;
  private timeline: Timeline;
  private inspector: Inspector;
  private images = new Map<string, HTMLImageElement>();
  private pose: LocalPose = { bones: [], slotAlpha: [] };

  /* sequence tester */
  private seqPlayer: PosePlayer | null = null;
  private seqRunner: SequenceRunner | null = null;

  /* redraw bookkeeping: things are only repainted when flagged */
  private visible = false;
  private raf = 0;
  private lastFrame = 0;
  private stageDirty = true;
  private timelineDirty = true;
  private pending = new Set<ChangeKind>();

  /* DOM bits that get refreshed */
  private animList = h('div', { class: 'anim-list', role: 'listbox', 'aria-label': 'Animations' });
  private animListSig = '';
  private boneTree = h('div', { class: 'bone-tree', role: 'listbox', 'aria-label': 'Bones' });
  private stageHolder = h('div', { class: 'stage-holder' });
  private playBtn!: HTMLButtonElement;
  private timeLabel = h('span', { class: 'time-label', title: 'Playhead: seconds · frame number (60 frames per second)' });
  private speedLabel = h('span', { class: 'muted speed-label' });
  private toolButtons = new Map<Tool, HTMLButtonElement>();
  private draftBanner = h('div', { class: 'banner notice', hidden: true });
  private renameBtn!: HTMLButtonElement;
  private deleteBtn!: HTMLButtonElement;
  private liveToggle!: ToggleButton;
  private draftTimer = 0;
  /** True once the user has previewed in the game: a restarted game is then sent the rig again. */
  private sentToGame = false;
  private liveTimer = 0;

  constructor(private shell: Shell, rig: RigData) {
    this.model = new AnimModel(rig);
    this.stage = new Stage(this.model, this.images, () => { const p = shell.currentConfig().player; return { w: p.width, h: p.height }; });
    this.timeline = new Timeline(this.model);
    this.inspector = new Inspector(this.model, {
      startSequence: (steps, repeat) => this.startSequence(steps, repeat),
      stopSequence: () => this.stopSequence(),
      sequenceIndex: () => (this.seqRunner && !this.seqRunner.done ? this.seqRunner.index : -1),
      exportAnimation: () => this.exportAnimation(),
    });

    this.stage.onDirty = () => { this.stageDirty = true; };
    this.stage.onPoseStart = () => this.pause();
    this.timeline.onDirty = () => { this.timelineDirty = true; };
    this.timeline.onInteract = () => { this.pause(); this.stopSequence(); };
    this.stageHolder.append(this.stage.canvas);
    new ResizeObserver(() => {
      this.stage.resize(this.stageHolder.clientWidth, this.stageHolder.clientHeight);
      this.stageDirty = true;
    }).observe(this.stageHolder);

    this.el = h('div', { class: 'tab-page anim-tab' },
      this.buildLeft(),
      h('main', { class: 'anim-center' },
        this.draftBanner, this.buildStageBar(), this.stageHolder, this.buildTransport(), this.buildTimelineBar(), this.timeline.el),
      this.inspector.el);

    this.model.onChange((kind) => this.pending.add(kind));
    // A game that (re)starts has only the SAVED rig: if we were previewing, send ours again.
    shell.link.onReady(() => { if (this.sentToGame && this.model.history.dirty) shell.link.sendRig(this.model.rig); });
    this.loadImages();
    this.timeline.rebuildRows();
    this.renderAnimList();
    this.renderBoneTree();
    this.syncTransport();
    this.syncTimeLabel();
    this.offerDraft(rig);
  }

  /* ================================================================== */
  /* EditorTab                                                           */
  /* ================================================================== */

  isDirty(): boolean { return this.model.history.dirty; }
  canUndo(): boolean { return this.model.history.canUndo; }
  canRedo(): boolean { return this.model.history.canRedo; }
  undo(): void { if (this.model.undo()) toast('Undone', 800); }
  redo(): void { if (this.model.redo()) toast('Redone', 800); }

  show(): void {
    this.visible = true;
    this.stageDirty = this.timelineDirty = true;
    this.lastFrame = performance.now();
    cancelAnimationFrame(this.raf);
    this.raf = requestAnimationFrame(this.tick);
  }
  hide(): void {
    this.visible = false;
    cancelAnimationFrame(this.raf);
    this.pause();
  }

  async save(): Promise<boolean> {
    const snapshot = this.model.rig;
    try {
      await saveContent(CONTENT.rig(snapshot.name || 'hero'), snapshot);
      this.model.history.markSaved(snapshot);
      this.clearDraft();
      this.shell.refresh();
      toast('Animations saved to hero.rig.json ✔');
      return true;
    } catch (err) {
      console.error(err);
      toast('Could not save the animations. Use "Export rig" to keep a copy.', 3500);
      return false;
    }
  }

  handleKey(e: KeyboardEvent): boolean {
    const m = this.model;
    const mod = e.ctrlKey || e.metaKey;
    const key = e.key.length === 1 ? e.key.toLowerCase() : e.key;
    // Arrow keys on a focused slider (e.g. playback speed) belong to the slider.
    if ((e.target as HTMLElement | null)?.tagName === 'INPUT' && key.startsWith('Arrow')) return false;
    if (mod) {
      if (key === 'c') { const n = m.copySelectedKeys(); if (n) toast(`Copied ${n} key${n === 1 ? '' : 's'}`, 900); return n > 0; }
      if (key === 'v') { this.pasteKeys(e.shiftKey); return true; }
      if (key === 'a') { this.selectAllKeys(); return true; }
      return false;
    }
    switch (key) {
      case ' ': this.togglePlay(); return true;
      case 'ArrowLeft': if (e.shiftKey) m.stepKey(-1); else m.stepFrames(-1); return true;
      case 'ArrowRight': if (e.shiftKey) m.stepKey(1); else m.stepFrames(1); return true;
      case ',': m.stepFrames(-1); return true;
      case '.': m.stepFrames(1); return true;
      case 'Home': this.pause(); m.setTime(0); return true;
      case 'End': this.pause(); m.setTime(m.duration); return true;
      case 'Delete': case 'Backspace': this.deleteSelection(); return true;
      case 'k': this.keySelectedBone(); return true;
      case 'r': this.setTool('rotate'); return true;
      case 'm': case 'g': this.setTool('move'); return true;
      case 's': this.setTool('scale'); return true;
      case 'Escape':
        if (this.seqRunner) this.stopSequence();
        else { m.selectKeys([]); m.selectBone(null); }
        return true;
    }
    return false;
  }

  /* ================================================================== */
  /* the frame loop                                                      */
  /* ================================================================== */

  private tick = (now: number): void => {
    if (!this.visible) return;
    this.raf = requestAnimationFrame(this.tick);
    const dt = Math.min(0.1, Math.max(0, (now - this.lastFrame) / 1000));
    this.lastFrame = now;
    const m = this.model;

    this.flushChanges();

    if (this.seqRunner && this.seqPlayer) {
      this.pose = this.seqRunner.update(dt * m.speed);
      this.stageDirty = true;
      this.inspector.syncSequence();
      this.syncTimeLabel();
      if (this.seqRunner.done) this.stopSequence();
    } else if (m.playing && m.anim) {
      let t = m.time + dt * m.speed;
      const d = m.duration;
      if (t >= d) {
        if (m.loopPreview && d > 0) t %= d;
        else { t = d; m.playing = false; this.syncTransport(); }
      }
      m.time = t;
      this.stageDirty = this.timelineDirty = true;
      this.syncTimeLabel();
    }

    if (this.stageDirty) {
      this.stageDirty = false;
      if (!this.seqRunner) sampleAnimation(m.rig, m.anim, m.time, this.pose);
      this.stage.draw(this.pose);
    }
    if (this.timelineDirty) {
      this.timelineDirty = false;
      this.timeline.draw();
    }
  };

  /** React to data changes at most once per frame, however many edits happened. */
  private flushChanges(): void {
    if (this.pending.size === 0) return;
    const kinds = this.pending;
    this.pending = new Set();
    this.stageDirty = this.timelineDirty = true;
    const doc = kinds.has('doc'), sel = kinds.has('selection');
    if (doc || sel) {
      this.timeline.rebuildRows();
      this.renderAnimList();
      this.syncBoneTree();
      this.inspector.sync();
      this.syncTransport();
      if (sel && this.model.selectedBone) this.timeline.revealBone(this.model.selectedBone);
    } else {
      if (kinds.has('view')) this.syncTransport();
      this.inspector.sync(true);
    }
    this.syncTimeLabel();
    if (doc) {
      this.seqPlayer?.setRig(this.model.rig);
      this.shell.refresh();
      this.scheduleDraft();
      if (this.liveToggle.pressed) {
        clearTimeout(this.liveTimer);
        this.liveTimer = window.setTimeout(() => this.sendToGame(), 60);
      }
    }
  }

  /* ================================================================== */
  /* images                                                              */
  /* ================================================================== */

  private loadImages(): void {
    for (const slot of this.model.rig.slots) {
      if (this.images.has(slot.image)) continue;
      const img = new Image();
      img.onload = () => this.stage.imagesChanged();
      img.onerror = () => console.warn(`[game editor] could not load ${slot.image}`);
      img.src = import.meta.env.BASE_URL + slot.image.replace(/^\//, '');
      this.images.set(slot.image, img);
    }
  }

  /* ================================================================== */
  /* left column: animations + bones                                     */
  /* ================================================================== */

  private buildLeft(): HTMLElement {
    this.renameBtn = button('✎ Rename', 'Rename the open animation', () => void this.renameAnim());
    this.deleteBtn = button('🗑 Delete', 'Delete the open animation', () => void this.deleteAnim());
    return h('aside', { class: 'anim-left' },
      h('section', { class: 'panel anim-list-panel' },
        h('h3', null, 'Animations'),
        this.animList,
        h('div', { class: 'list-buttons' },
          button('+ New', 'Make a new, empty animation', () => void this.newAnim(false)),
          button('⧉ Copy', 'Make a copy of the open animation to experiment on', () => void this.newAnim(true)),
          this.renameBtn, this.deleteBtn,
          button('⬇ Export rig', 'Download the whole rig (all animations) as a JSON file', () => downloadJson(`${this.model.rig.name || 'hero'}.rig.json`, this.model.rig)),
          button('⬆ Import', 'Import an exported animation or a whole rig file', () => void this.importFile())),
        h('div', { class: 'file-note muted', title: 'hero.rig.json is normally generated from tools/art/hero-anims.mjs. Saving here edits the JSON directly.' },
          'ⓘ Saved edits live in hero.rig.json; re-running ', h('code', null, 'npm run art'), ' would overwrite them.')),
      h('section', { class: 'panel bone-panel' },
        h('h3', null, 'Bones'),
        this.boneTree));
  }

  private renderAnimList(): void {
    const { rig, animName } = this.model;
    const sig = animName + '|' + Object.entries(rig.animations).map(([n, a]) => `${n}:${a.duration}:${a.loop}`).join(',');
    if (sig === this.animListSig) return;
    this.animListSig = sig;
    clear(this.animList);
    for (const [name, anim] of Object.entries(rig.animations)) {
      const locked = isProtectedAnim(name);
      this.animList.append(h('button', {
        type: 'button', role: 'option', class: `anim-item${name === animName ? ' active' : ''}`, 'aria-selected': String(name === animName), 'data-anim': name,
        title: `${name}: ${anim.duration} s, ${anim.loop ? 'loops' : 'plays once'}${locked ? ' - used by the game (cannot be renamed or deleted)' : ''}`,
        onclick: () => { this.stopSequence(); this.model.openAnimation(name); },
      },
        h('span', { class: 'anim-name' }, name),
        h('span', { class: 'anim-meta muted' }, `${anim.loop ? '∞' : '→'} ${anim.duration}s${locked ? ' 🔒' : ''}`)));
    }
    const locked = isProtectedAnim(animName);
    this.renameBtn.disabled = this.deleteBtn.disabled = locked || !animName;
    this.renameBtn.title = locked ? `"${animName}" is used by the game, so it cannot be renamed` : 'Rename the open animation';
    this.deleteBtn.title = locked ? `"${animName}" is used by the game, so it cannot be deleted` : 'Delete the open animation';
  }

  private renderBoneTree(): void {
    clear(this.boneTree);
    const rig = this.model.rig;
    const depth = new Map<string, number>();
    for (const b of rig.bones) depth.set(b.name, b.parent ? (depth.get(b.parent) ?? 0) + 1 : 0);
    for (const b of rig.bones) {
      this.boneTree.append(h('button', {
        type: 'button', role: 'option', class: 'bone-item', 'data-bone': b.name,
        style: { paddingLeft: `${8 + Math.min(depth.get(b.name) ?? 0, 6) * 12}px` },
        title: `Select the "${b.name}" bone`,
        onclick: () => this.model.selectBone(b.name),
      }, b.name));
    }
    this.syncBoneTree();
  }

  private syncBoneTree(): void {
    for (const el of Array.from(this.boneTree.children) as HTMLElement[]) {
      const on = el.dataset.bone === this.model.selectedBone;
      if (on && !el.classList.contains('active')) el.scrollIntoView({ block: 'nearest' });
      el.classList.toggle('active', on);
    }
  }

  private async newAnim(duplicate: boolean): Promise<void> {
    const m = this.model;
    const source = duplicate ? m.anim : undefined;
    if (duplicate && !source) return;
    const suggestion = uniqueAnimName(m.rig, duplicate ? `${m.animName}2` : 'newAnim');
    const name = await askText(duplicate ? `Copy "${m.animName}"` : 'New animation',
      'Name (letters and numbers, no spaces):', suggestion, (v) => checkAnimName(m.rig, v));
    if (!name) return;
    m.setRig(withAnimation(m.rig, name, source ? cloneAnimation(source) : blankAnimation()));
    m.openAnimation(name);
    toast(duplicate ? `Copied to "${name}"` : `Created "${name}" - pose the hero and keys appear at the playhead`, 2600);
  }

  private async renameAnim(): Promise<void> {
    const m = this.model;
    const from = m.animName;
    if (isProtectedAnim(from)) { toast(`"${from}" is used by the game and cannot be renamed. Make a copy instead.`, 3000); return; }
    const name = await askText(`Rename "${from}"`, 'New name:', from, (v) => checkAnimName(m.rig, v, from));
    if (!name || name === from) return;
    const next = renameAnimation(m.rig, from, name);
    m.animName = name;
    m.setRig(next);
    m.emit('selection');
  }

  private async deleteAnim(): Promise<void> {
    const m = this.model;
    const name = m.animName;
    if (isProtectedAnim(name)) { toast(`"${name}" is used by the game and cannot be deleted.`, 3000); return; }
    if (!(await askConfirm('Delete animation', `Delete "${name}"? (You can undo this.)`, 'Delete', true))) return;
    m.setRig(deleteAnimation(m.rig, name));
    m.emit('selection');
  }

  /* ================================================================== */
  /* stage toolbar                                                       */
  /* ================================================================== */

  private setTool(tool: Tool): void {
    this.model.tool = tool;
    for (const [t, b] of this.toolButtons) { b.classList.toggle('active', t === tool); b.setAttribute('aria-pressed', String(t === tool)); }
    this.stageDirty = true;
  }

  private buildStageBar(): HTMLElement {
    const tool = (t: Tool, label: string, title: string) => {
      const b = button(label, title, () => this.setTool(t), 'toggle');
      this.toolButtons.set(t, b);
      return b;
    };
    const v = this.stage.view;
    const redraw = () => { this.stageDirty = true; };
    const bg = h('span', { class: 'swatches', title: 'Background colour (only in this editor)' },
      ...BACKGROUNDS.map((b) => {
        const sw = button('', `${b.name} background`, () => {
          v.background = b.color; redraw();
          for (const el of Array.from(bg.children)) el.classList.toggle('active', el === sw);
        }, `swatch${b.color === v.background ? ' active' : ''}`);
        sw.style.background = b.color;
        return sw;
      }));
    const bar = h('div', { class: 'stage-bar' },
      h('span', { class: 'bar-group', role: 'group', 'aria-label': 'Posing tool' },
        tool('rotate', '⟳ Rotate', 'Drag a body part to turn it (R). Hold Shift for 5° steps.'),
        tool('move', '✥ Move', 'Drag a body part to slide it (M). Best for the hip.'),
        tool('scale', '⤢ Scale', 'Drag the square handles to stretch a body part (S).')),
      h('span', { class: 'bar-group' },
        toggleButton('🦴 Bones', 'Show the skeleton on top of the hero', v.showBones, (on) => { v.showBones = on; redraw(); }),
        toggleButton('👻 Onion', 'Onion skin: ghost of the previous key (blue) and the next key (orange)', v.onion, (on) => { v.onion = on; redraw(); }),
        toggleButton('▭ Box', 'Show the collision box from the Game Feel tab (body width × height)', v.showBox, (on) => { v.showBox = on; redraw(); }),
        toggleButton('⇄ Flip', 'Face the other way (only in this editor)', v.flip, (on) => { v.flip = on; redraw(); }),
        button('⊡ Fit', 'Centre the hero and reset the zoom (or double-click empty space)', () => { this.stage.fit(); redraw(); })),
      bg);
    this.setTool('rotate');
    return bar;
  }

  private sendToGame(): void {
    this.sentToGame = true;
    this.shell.link.sendRig(this.model.rig);
  }

  /* ================================================================== */
  /* play controls                                                       */
  /* ================================================================== */

  /** Stop playback, parking the playhead on a whole frame so new keys land on the 1/60 s grid. */
  private pause(): void {
    if (!this.model.playing) return;
    this.model.playing = false;
    this.model.time = Math.min(snapTime(this.model.time), this.model.duration);
    this.model.emit('view');
  }

  private togglePlay(): void {
    const m = this.model;
    if (this.seqRunner) { this.stopSequence(); return; }
    if (m.playing) { this.pause(); return; }
    if (m.time >= m.duration - 1e-6) m.time = 0;
    m.playing = true;
    m.emit('view');
  }

  private buildTransport(): HTMLElement {
    const m = this.model;
    this.playBtn = button('▶', 'Play / pause (Space)', () => this.togglePlay(), 'primary play-btn');
    this.liveToggle = toggleButton('Live', 'Keep sending every change to the running game straight away', false, (on) => { if (on) this.sendToGame(); });
    const speed = h('input', {
      type: 'range', min: 0.1, max: 2, step: 0.05, value: '1', class: 'speed-slider', title: 'Playback speed (0.1× slow motion to 2×)', 'aria-label': 'Playback speed',
      oninput: () => { m.speed = Number(speed.value); this.speedLabel.textContent = `${m.speed.toFixed(2)}×`; },
      ondblclick: () => { speed.value = '1'; m.speed = 1; this.speedLabel.textContent = '1.00×'; },
    });
    this.speedLabel.textContent = '1.00×';
    return h('div', { class: 'transport' },
      button('⏮', 'Back to the start (Home)', () => { this.pause(); m.setTime(0); }, 'mini'),
      button('◆◀', 'Previous key (Shift+←)', () => m.stepKey(-1), 'mini'),
      button('◀', 'One frame back (← or ,)', () => m.stepFrames(-1), 'mini'),
      this.playBtn,
      button('▶', 'One frame forward (→ or .)', () => m.stepFrames(1), 'mini'),
      button('▶◆', 'Next key (Shift+→)', () => m.stepKey(1), 'mini'),
      button('⏭', 'To the end (End)', () => { this.pause(); m.setTime(m.duration); }, 'mini'),
      toggleButton('🔁', 'Keep repeating while previewing (even animations that play once in the game)', m.loopPreview, (on) => { m.loopPreview = on; }),
      this.timeLabel,
      h('span', { class: 'spacer' }),
      speed, this.speedLabel,
      button('📡 To game', 'Show these animations on the hero in the running game (the Game Feel tab or a popped-out game) without saving', () => { this.sendToGame(); toast('Sent to the game'); }),
      this.liveToggle);
  }

  private syncTransport(): void {
    const playing = this.model.playing || !!this.seqRunner;
    this.playBtn.textContent = playing ? '⏸' : '▶';
    this.playBtn.title = this.seqRunner ? 'Stop the sequence (Space)' : 'Play / pause (Space)';
  }

  private syncTimeLabel(): void {
    const m = this.model;
    const text = this.seqRunner ? `sequence: ${this.seqPlayer?.current ?? ''}` : `${m.time.toFixed(3)} s · frame ${Math.round(m.time * 60)}/${Math.round(m.duration * 60)}`;
    if (this.timeLabel.textContent !== text) this.timeLabel.textContent = text;
  }

  /* ================================================================== */
  /* timeline toolbar (key actions)                                      */
  /* ================================================================== */

  private buildTimelineBar(): HTMLElement {
    const m = this.model;
    return h('div', { class: 'timeline-bar' },
      h('span', { class: 'bar-group' },
        button('◆ Key bone', 'Add a rotation key for the selected bone at the playhead (K)', () => this.keySelectedBone()),
        button('◆◆ Key all', 'Freeze the whole pose into keys at the playhead', () => this.keyAll())),
      h('span', { class: 'bar-group' },
        button('Copy pose', 'Remember the whole pose at the playhead', () => {
          if (!m.anim) return;
          m.poseClip = copyPoseAt(m.anim, m.time, m.rig);
          toast('Pose copied - move the playhead (or open another animation) and paste', 2200);
        }),
        button('Paste pose', 'Key the remembered pose at the playhead', () => {
          if (!m.anim || !m.poseClip) { toast('Copy a pose first'); return; }
          const res = pastePoseAt(m.anim, m.poseClip, roundTime(m.time), m.rig);
          m.selectedKeys = res.refs;
          m.setAnim(res.anim);
          m.emit('selection');
          toast(`Pasted the pose (${res.refs.length} keys)`);
        })),
      h('span', { class: 'bar-group' },
        button('⧉', 'Copy the selected keys (Ctrl+C)', () => { const n = m.copySelectedKeys(); toast(n ? `Copied ${n} key${n === 1 ? '' : 's'}` : 'Select some keys first', 1000); }, 'mini'),
        button('📋', 'Paste keys at the playhead (Ctrl+V)', () => this.pasteKeys(false), 'mini'),
        button('📋⇄', 'Paste keys backwards in time: the last key comes first (Ctrl+Shift+V)', () => this.pasteKeys(true), 'mini'),
        button('🗑', 'Delete the selected keys or event (Delete)', () => this.deleteSelection(), 'mini')),
      button('⚑ Event', 'Add a named moment (like "step" or "hit") at the playhead', () => void this.addEventHere()),
      h('span', { class: 'spacer' }),
      toggleButton('⇕ Tall', 'Make the timeline taller (and the stage smaller)', false, (on) => { this.timeline.el.classList.toggle('tall', on); }),
      toggleButton('All pictures', 'Also show rows for body-part pictures that have no see-through keys yet', false, (on) => { this.timeline.showAllSlots = on; this.timeline.rebuildRows(); this.timelineDirty = true; }));
  }

  private keySelectedBone(): void {
    const m = this.model;
    if (!m.anim || !m.selectedBone) { toast('Select a bone first'); return; }
    const ref = { kind: 'bone' as const, target: m.selectedBone, channel: 'rotation' as const };
    const t = roundTime(m.time);
    m.selectedKeys = [{ ...ref, t }];
    m.keyAtPlayhead(ref, sampleOffset(m.anim, ref, t, m.rig));
    m.emit('selection');
  }

  private keyAll(): void {
    const m = this.model;
    if (!m.anim) return;
    const res = keyAllBones(m.rig, m.anim, roundTime(m.time));
    m.selectedKeys = res.refs;
    m.setAnim(res.anim);
    m.emit('selection');
    toast(`Keyed the whole pose (${res.refs.length} keys)`);
  }

  private pasteKeys(mirror: boolean): void {
    if (!this.model.keyClip) { toast('Copy some keys first (Ctrl+C)'); return; }
    const n = this.model.pasteKeysAtPlayhead(mirror);
    toast(n ? `Pasted ${n} key${n === 1 ? '' : 's'}${mirror ? ' backwards' : ''}` : 'Nothing fits here - move the playhead earlier', 1400);
  }

  private selectAllKeys(): void {
    const m = this.model;
    if (!m.anim) return;
    const all = [];
    for (const [bone, track] of Object.entries(m.anim.bones)) {
      for (const [channel, keys] of Object.entries(track)) for (const k of keys ?? []) all.push({ kind: 'bone' as const, target: bone, channel: channel as 'rotation', t: k.t });
    }
    for (const [slot, track] of Object.entries(m.anim.slots ?? {})) for (const k of track.alpha ?? []) all.push({ kind: 'slot' as const, target: slot, channel: 'alpha' as const, t: k.t });
    m.selectKeys(all);
  }

  private deleteSelection(): void {
    const m = this.model;
    if (m.selectedEvent !== null && m.anim) {
      const i = m.selectedEvent;
      m.selectedEvent = null;
      m.setAnim(deleteEvent(m.anim, i));
      return;
    }
    const n = m.deleteSelectedKeys();
    if (n) toast(`Deleted ${n} key${n === 1 ? '' : 's'}`, 900);
  }

  private async addEventHere(): Promise<void> {
    const m = this.model;
    if (!m.anim) return;
    const t = roundTime(m.time);
    const name = await askText('New event', 'Name this moment (the game listens for "step" and "hit"):', 'step');
    if (!name || !m.anim) return;
    const res = addEvent(m.anim, t, name);
    m.setAnim(res.anim);
    m.selectEvent(res.index);
  }

  /* ================================================================== */
  /* export / import                                                     */
  /* ================================================================== */

  private exportAnimation(): void {
    const m = this.model;
    if (!m.anim) return;
    downloadJson(`${m.animName}.anim.json`, { type: 'animation', name: m.animName, animation: m.anim });
  }

  private async importFile(): Promise<void> {
    const m = this.model;
    const raw = (await pickJsonFile()) as Record<string, unknown> | null;
    if (!raw || typeof raw !== 'object') { toast('That file could not be read as JSON'); return; }
    if (Array.isArray(raw.bones) && raw.animations && typeof raw.animations === 'object') {
      // a whole rig: take its animations and blend times, keep our own bones/pictures (setup pose is not editable here)
      const incoming = raw as unknown as RigData;
      if (!(await askConfirm('Import rig', `Replace ALL animations with the ${Object.keys(incoming.animations).length} in this file? (You can undo.)`, 'Replace'))) return;
      m.setRig({ ...m.rig, animations: incoming.animations, mix: incoming.mix ?? m.rig.mix });
      m.emit('selection');
      toast('Animations imported');
      return;
    }
    const anim = raw.animation as RigData['animations'][string] | undefined;
    if (anim && typeof anim.duration === 'number' && anim.bones && typeof anim.bones === 'object') {
      let name = typeof raw.name === 'string' && !checkAnimName(m.rig, raw.name, raw.name) ? raw.name : 'imported';
      if (m.rig.animations[name] && !(await askConfirm('Import animation', `Replace the animation "${name}" with the one in this file? Choose Cancel to import it as a copy.`, 'Replace'))) {
        name = uniqueAnimName(m.rig, `${name}2`);
      }
      m.setRig(withAnimation(m.rig, name, { ...anim, loop: !!anim.loop }));
      m.openAnimation(name);
      m.emit('selection');
      toast(`Imported "${name}"`);
      return;
    }
    toast('That file is not an exported animation or rig');
  }

  /* ================================================================== */
  /* sequence tester                                                     */
  /* ================================================================== */

  private startSequence(steps: SequenceStep[], repeat: boolean): void {
    if (steps.length === 0) { toast('Add some animations to the sequence first'); return; }
    this.model.playing = false;
    this.seqPlayer = new PosePlayer(this.model.rig);
    this.seqRunner = new SequenceRunner(this.seqPlayer, this.model.rig, steps, repeat);
    this.stage.locked = true;
    this.syncTransport();
    this.inspector.syncSequence(true);
  }

  private stopSequence(): void {
    if (!this.seqRunner) return;
    this.seqRunner = null;
    this.seqPlayer = null;
    this.stage.locked = false;
    this.stageDirty = true;
    this.syncTransport();
    this.syncTimeLabel();
    this.inspector.syncSequence(true);
  }

  /* ================================================================== */
  /* drafts: unsaved work survives a closed tab                          */
  /* ================================================================== */

  private scheduleDraft(): void {
    clearTimeout(this.draftTimer);
    this.draftTimer = window.setTimeout(() => {
      try {
        if (this.model.history.dirty) localStorage.setItem(DRAFT_KEY, JSON.stringify({ savedAt: Date.now(), rig: this.model.rig }));
        else localStorage.removeItem(DRAFT_KEY);
      } catch { /* storage full or blocked: drafts are a bonus, not essential */ }
    }, 700);
  }

  private clearDraft(): void {
    clearTimeout(this.draftTimer);
    try { localStorage.removeItem(DRAFT_KEY); } catch { /* ignore */ }
  }

  /** If the browser holds unsaved work from last time, offer to bring it back. */
  private offerDraft(loaded: RigData): void {
    let draft: { savedAt: number; rig: RigData } | null = null;
    try { draft = JSON.parse(localStorage.getItem(DRAFT_KEY) ?? 'null'); } catch { draft = null; }
    if (!draft || !draft.rig || !Array.isArray(draft.rig.bones) || !draft.rig.animations) return;
    const same = JSON.stringify({ a: draft.rig.animations, m: draft.rig.mix }) === JSON.stringify({ a: loaded.animations, m: loaded.mix });
    if (same) { this.clearDraft(); return; }
    const when = new Date(draft.savedAt).toLocaleString();
    const close = () => { this.draftBanner.hidden = true; };
    clear(this.draftBanner);
    this.draftBanner.append(
      h('span', null, h('strong', null, 'Unsaved animation work found '), `from ${when}. Bring it back?`),
      button('Restore', 'Continue from the unsaved work', () => {
        // keep the freshly loaded bones/pictures; restore animations + blend times
        this.model.setRig({ ...this.model.rig, animations: draft!.rig.animations, mix: draft!.rig.mix });
        this.model.emit('selection');
        close();
        toast('Restored - remember to Save');
      }, 'primary'),
      button('Throw away', 'Forget the unsaved work', () => { this.clearDraft(); close(); }));
    this.draftBanner.hidden = false;
  }
}
